#!/usr/bin/env bash
# Creates the git-ignored .env with random secrets for local runs and docker compose.
# Keeps an existing .env unless --force is given. Never commit .env.
set -euo pipefail
cd "$(dirname "$0")/.."

if [[ -f .env && "${1:-}" != "--force" ]]; then
  echo ".env already exists (use --force to regenerate)"
  exit 0
fi

rand() { od -An -tx1 -N"$1" /dev/urandom | tr -d ' \n'; }

umask 077
cat > .env <<EOF
# Generated by scripts/init-env.sh on $(date -u +%FT%TZ). Local secrets: never commit this file.
JWT_SECRET=$(rand 32)
DB_PASSWORD=$(rand 16)
DEMO_OPERATOR_PASSWORD=op-$(rand 12)
DEMO_ADMIN_PASSWORD=admin-$(rand 12)
DEMO_EMPLOYEE_PASSWORD=emp-$(rand 12)
DEMO_SERVICE_PASSWORD=svc-$(rand 12)
EOF
echo "wrote .env with random secrets (demo passwords: grep DEMO_ .env)"
